$line = (Get-Content -LiteralPath "$env:USERPROFILE\.claude\projects\d---ntu---aiProject--dev\84bcb93b-9920-4f4c-8baf-2b325914c8d1.jsonl")[25]
$targets = @('3Qh79T','rKf6t4','Ab8RN6','54837c','13ca1b')
foreach ($t in $targets) {
  $idx = $line.IndexOf($t)
  if ($idx -ge 0) {
    $start = [Math]::Max(0, $idx-60)
    $ctx = $line.Substring($start, [Math]::Min(90, $line.Length-$start))
    # mask any long token-looking substring in the context
    $ctxMasked = [regex]::Replace($ctx, '[A-Za-z0-9_\-]{20,}', { param($m) $m.Value.Substring(0,4) + '...MASKED...' })
    "ctx: $ctxMasked"
  }
}

